use canvas::Canvas;

/// Smallest supported texture size: the native resolution of the designs.
pub const MIN_SIZE: u32 = 16;
/// Largest supported texture size.
pub const MAX_SIZE: u32 = 256;

/// Paints the texture `recipe` with the given parameters, seed and size.
///
/// `size` is the edge length in texels: a power of two from [`MIN_SIZE`] to [`MAX_SIZE`].
/// Different seeds give different textures of the same material; the same request always
/// gives the same texture.
///
/// # Errors
/// - [`ProcTexError::UnknownRecipe`] if `recipe` is not one of [`recipes`];
/// - [`ProcTexError::UnsupportedSize`] if `size` is not supported;
/// - [`ProcTexError::UnknownParam`], [`ProcTexError::WrongParamKind`] or
///   [`ProcTexError::UnknownVariant`] if `params` does not fit the recipe.
pub fn generate(
    recipe: &str,
    params: &Params,
    seed: u64,
    size: u32,
) -> Result<PbrTexture, ProcTexError> {
    generate_window(recipe, params, seed, size, (0, 0))
}

/// [`generate`] for the window of the tiled plane that starts `origin` texels away from the
/// tile's corner. A seamless texture gives the same image, rolled by `origin`.
pub(crate) fn generate_window(
    recipe: &str,
    params: &Params,
    seed: u64,
    size: u32,
    origin: (i64, i64),
) -> Result<PbrTexture, ProcTexError> {
    let entry = recipes::find(recipe).ok_or_else(|| ProcTexError::UnknownRecipe {
        recipe: recipe.to_owned(),
    })?;
    if !size.is_power_of_two() || !(MIN_SIZE..=MAX_SIZE).contains(&size) {
        return Err(ProcTexError::UnsupportedSize { size });
    }
    entry.check(params)?;
    let canvas = Canvas::new(entry.info.name, seed, size as usize, origin);
    Ok((entry.paint)(&canvas, params).finish())
}
